'use client';

import React, { createContext, useContext, useState, ReactNode } from 'react';

// Define the shape of our context
interface TooltipContextType {
  activeTooltipId: string | null;
  openTooltip: (id: string) => void;
  closeTooltip: () => void;
}

const TooltipContext = createContext<TooltipContextType | undefined>(undefined);

export const TooltipProvider: React.FC<{ children: ReactNode }> = ({ children }) => {
  const [activeTooltipId, setActiveTooltipId] = useState<string | null>(null);

  const openTooltip = (id: string) => {
    // Optional: Add a small delay if you want to prevent rapid clicking
    // setTimeout(() => setActiveTooltipId(id), 50); 
    setActiveTooltipId(id);
  };

  const closeTooltip = () => {
    setActiveTooltipId(null);
  };

  return (
    <TooltipContext.Provider value={{ activeTooltipId, openTooltip, closeTooltip }}>
      {children}
    </TooltipContext.Provider>
  );
};

export const useTooltip = () => {
  const context = useContext(TooltipContext);
  if (!context) {
    throw new Error('useTooltip must be used within a TooltipProvider');
  }
  return context;
};
